def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """

    # Convert the input string to lowercase and split it into a list of characters
    test = test.lower()
    char_list = list(test)

    # Create an empty dictionary to store the frequency of each character
    freq_dict = {}

    # Iterate through the list of characters and count their occurrences
    for char in char_list:
        if char in freq_dict:
            freq_dict[char] += 1
        else:
            freq_dict[char] = 1

    # Return the dictionary containing the most frequent character and its count
    max_count = max(freq_dict.values())
    return {k: v for k, v in freq_dict.items() if v == max_count}
```
